public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    List<Integer> A = new ArrayList<>();
    int n = sc.nextInt();
    for (int i = 0; i < n; i++) {
        A.add(sc.nextInt());
    }
    sc.close();

    List<Integer> left = new ArrayList<>(Collections.nCopies(n, 1));
    List<Integer> right = new ArrayList<>(Collections.nCopies(n, 1));

    for (int i = 1; i < n; i++) {
        if (A.get(i) > A.get(i - 1)) {
            left.set(i, left.get(i - 1) + 1);
        }
    }

    for (int i = n - 2; i >= 0; i--) {
        if (A.get(i) > A.get(i + 1)) {
            right.set(i, right.get(i + 1) + 1);
        }
    }

    int max_pyramid_size = 0;
    for (int i = 0; i < n; i++) {
        int pyramid_size = left.get(i) + right.get(i) - 1;
        if (pyramid_size > max_pyramid_size) {
            max_pyramid_size = pyramid_size;
        }
    }

    System.out.print(max_pyramid_size);
}
